changeSet.sql:
ALTER TABLE dl_identity_outbox
 ADD COLUMN claim_token uuid,
 ADD COLUMN claim_until timestamptz,
 ADD COLUMN published_at timestamptz;
CREATE INDEX dl_identity_outbox_pending ON dl_identity_outbox (created_at_ms, event_id)
 WHERE published_at IS NULL;
CREATE INDEX dl_identity_outbox_published ON dl_identity_outbox (published_at, event_id)
 WHERE published_at IS NOT NULL;
